#include "../src/AlphaSimulation.h"
#include <iostream>
#include <stdexcept>
using namespace alpha;
int checks=0;
void check(bool ok,const char* name){if(!ok)throw std::runtime_error(name);++checks;std::cout<<"PASS "<<name<<std::endl;}
void advance(World& w,float seconds){for(int i=0;i<int(seconds*20);++i)w.step(.05f);}
int main(){try{
 {World w;w.reset();w.raidsEnabled=false;int trees=0;for(auto& e:w.entities)if(e.kind==Kind::Forest&&e.hp>0)++trees;std::cout<<"TREES "<<trees<<std::endl;check(trees>350,"richer map has more than 350 individual trees");int wood=w.wood;for(int id=7;id<=10;++id){w.gather(*w.get(id),4);check(w.get(id)->order==Order::Gather,"inner-tree click finds accessible forest edge");}
 bool carried[4]={};for(int i=0;i<2400;++i){w.step(.05f);for(int id=7;id<=10;++id)if(w.get(id)->cargo>0)carried[id-7]=true;}check(w.wood>=wood+200,"four workers deliver timber for two simulated minutes");for(bool value:carried)check(value,"every assigned worker reaches and harvests the grove");
 }
 {World w;w.reset();w.raidsEnabled=false;w.gather(*w.get(7),4);bool cutting=false;for(int i=0;i<600;++i){w.step(.05f);auto e=w.get(7);if(e->order==Order::Gather&&e->route.empty()&&e->work>.5f){float work=e->work;w.gather(*e,e->target);check(e->work==work,"repeated order does not restart chopping progress");cutting=true;break;}}check(cutting,"worker reaches visible chopping state");}
 {World w;w.reset();w.raidsEnabled=false;w.gather(*w.get(7),4);bool carrying=false;for(int i=0;i<600;++i){w.step(.05f);if(w.get(7)->cargo>0){carrying=true;break;}}check(carrying,"worker obtains timber cargo");int cargo=w.get(7)->cargo,wood=w.wood;w.gather(*w.get(7),6);check(w.get(7)->cargo==cargo&&w.get(7)->order==Order::Return,"new harvest order preserves cargo and returns it first");advance(w,20);check(w.wood>=wood+cargo,"preserved cargo is credited on delivery");}
 {World w;w.reset();w.raidsEnabled=false;for(auto& e:w.entities)if(e.kind==Kind::Forest)e.hp=0;w.add(Kind::LumberMill,0,{600,750});int first=w.add(Kind::Forest,-1,{700,900});int second=w.add(Kind::Forest,-1,{800,900});w.get(first)->hp=w.get(second)->hp=10;w.get(7)->pos={650,850};int wood=w.wood;w.gather(*w.get(7),first);advance(w,80);check(!w.get(first)&&!w.get(second),"worker advances to the next tree after felling one");check(w.wood>=wood+20,"last timber of exhausted grove is delivered");check(w.get(7)->order==Order::Idle,"worker stops cleanly when the grove is exhausted");}
 for(int x=0;x<40;x+=10)for(int y=0;y<40;y+=10){World w;w.reset();w.raidsEnabled=false;for(auto& e:w.entities)if(e.kind==Kind::Forest)e.hp=0;int tree=w.add(Kind::Forest,-1,{800.f+x,880.f+y});w.get(7)->pos={700,750};w.gather(*w.get(7),tree);advance(w,8);check(w.get(tree)->hp<80,"isolated tree is harvestable at varied map positions");}

 {World w;w.reset();w.raidsEnabled=false;check(w.visibleAt({280,750}),"starting base visible immediately");check(!w.exploredAt({2200,750}),"enemy base starts unexplored");check(!w.exploredAt({1280,800}),"middle of map starts unexplored");w.get(11)->pos={1280,800};w.refreshVision();check(w.visibleAt({1280,800})&&w.exploredAt({1280,800}),"unit reveals new terrain");w.get(11)->pos={520,700};w.refreshVision();check(w.exploredAt({1280,800})&&!w.visibleAt({1280,800}),"explored terrain remains known after departure");w.refreshVision();check(!w.exploredAt({2200,750}),"enemy vision does not reveal terrain to player");w.reset();check(!w.exploredAt({1280,800}),"new game clears exploration");w.prepareArsenal();check(w.visibleAt({2200,750}),"arsenal intentionally reveals entire map");check(!w.exploredAt({-1,500}),"out of bounds remains invalid");}
 {World w;w.reset();w.raidsEnabled=false;for(auto& e:w.entities)if(e.kind==Kind::Forest)e.hp=0;int tree=w.add(Kind::Forest,-1,{800,800});w.get(tree)->hp=10;w.get(7)->pos={700,800};w.gold=w.wood=1000;check(!w.placementIssue({800,800},Kind::Farm).empty(),"living tree prevents foundation placement");int gold=w.gold;check(!w.build(7,{800,800},Kind::Farm)&&w.gold==gold&&w.get(tree),"construction cannot clear living trees for free");check(w.blocked(20,20),"living tree occupies navigation grid");w.gather(*w.get(7),tree);advance(w,30);check(!w.get(tree),"fully harvested tree removed from active world");check(!w.blocked(20,20),"felled tree frees navigation grid");check(w.build(7,{800,800},Kind::Farm),"farm can occupy the exact felled tree position");}
 {World w;w.reset();w.raidsEnabled=false;w.gold=w.wood=1000;w.get(3)->hp=10;w.get(7)->pos={470,620};check(!w.placementIssue({470,500},Kind::Farm).empty(),"live mine blocks foundations");w.gather(*w.get(7),3);advance(w,30);check(!w.get(3),"mine disappears after last resource load");check(w.build(7,{470,500},Kind::Farm),"exhausted mine frees its position for construction");}
 {World w;w.reset();w.raidsEnabled=false;w.gold=w.wood=w.oil=10000;w.townLevel[0]=3;int a=w.add(Kind::Forge,0,{800,750}),b=w.add(Kind::Forge,0,{1000,750});check(w.research(a,Research::Weapons),"global upgrade starts");check(!w.research(b,Research::Weapons),"duplicate global research cannot exceed maximum in parallel");check(w.cancel(a)&&w.research(b,Research::Weapons),"cancelled research can restart in another producer");advance(w,13);check(w.upgrades[0][int(Research::Weapons)]==1,"first upgrade level applied once");check(w.research(b,Research::Weapons),"second upgrade level starts");advance(w,13);check(w.upgrades[0][int(Research::Weapons)]==2&&!w.research(a,Research::Weapons),"maximum upgrade level enforced");check(!w.research(1,Research::Town2)&&w.townLevel[0]==3,"completed command cannot be downgraded by old research");}
 std::cout<<"SUCCESS "<<checks<<" forest regression checks"<<std::endl;return 0;
}catch(const std::exception& e){std::cerr<<"FAIL "<<e.what()<<std::endl;return 1;}}

